// La clave viene en el enlace (?k=...). Sin la forma exacta no se consulta nada: no
// hay por qué preguntarle a Directus por una cadena cualquiera que llegue de fuera.
const q = ($json.query) || {};
const k = String(q.k || '').trim().toLowerCase();
return [{ json: { k, valida: /^[0-9a-f]{32}$/.test(k) } }];

// Un empleado dado de baja deja de publicar: su calendario se queda vacío para quien
// lo tuviera suscrito, en vez de seguir enseñando citas de clientes.
const r = $json ?? {};
if (!(r.statusCode >= 200 && r.statusCode < 300)) {
  throw new Error('Directus devolvió ' + r.statusCode + ' al buscar el empleado: ' + JSON.stringify(r.body).slice(0, 300));
}
const emp = ((r.body && r.body.data) || [])[0];
if (!emp || String(emp.status || '').toLowerCase() !== 'active') return [{ json: { existe: false } }];
const desde = DateTime.now().minus({ days: 30 }).toUTC().toISO();
const hasta = DateTime.now().plus({ days: 180 }).toUTC().toISO();
// Aquí solo se acota por estado y fechas. QUIÉN la atiende se decide en `Code · ICS`, en
// código: el filtro relacional de Directus (`recursos._some -> resource_id.employee_id`)
// se ignoraba en silencio y cada enlace salía con las citas de TODO el negocio -- la demo
// de un recurso sin empleado apareció en el calendario de Arturo (8/oct/2026).
const filtro = { _and: [
  { status: { _in: ['scheduled', 'confirmed'] } },
  { end_at: { _gte: desde } },
  { start_at: { _lte: hasta } },
] };
return [{ json: { existe: true, emp, filtro: JSON.stringify(filtro) } }];

// El calendario en formato iCalendar (RFC 5545). Cada vez que el calendario del
// empleado lo pide se genera entero, así que una cita anulada simplemente deja de
// estar: no hace falta "borrar" nada.
//
// Una clase en grupo (recurso con capacidad > 1) es UN evento con la lista de
// apuntados, igual que en la sincronización con Outlook.
const r = $json ?? {};
if (!(r.statusCode >= 200 && r.statusCode < 300)) {
  throw new Error('Directus devolvió ' + r.statusCode + ' al leer las citas: ' + JSON.stringify(r.body).slice(0, 300));
}
const citas = (r.body && r.body.data) || [];
const emp = $('Code · ¿Existe?').first().json.emp;
const negocio = $('Config (editar por tenant)').first().json.negocio;

// Texto de iCalendar: \ ; , y saltos de línea se escapan.
const txt = (s) => String(s ?? '').replace(/\\/g, '\\\\').replace(/;/g, '\\;').replace(/,/g, '\\,')
  .replace(/\r?\n/g, '\\n');
const utc = (s) => DateTime.fromISO(s, { zone: 'utc' }).toFormat("yyyyLLdd'T'HHmmss'Z'");
const nombre = (ct) => [ct && ct.first_name, ct && ct.last_name].filter(Boolean).join(' ')
  || (ct && ct.company) || 'Cliente';
const telefono = (ct) => ((ct && ct.phones) || []).map((p) => p.phone_number).filter(Boolean)[0] || '';
const PIE = 'Reservada con Aegora. Para cambiarla o anularla, hazlo en el panel de Aegora: lo que se cambie aquí no llega al cliente.';

// Las líneas no pueden pasar de 75 OCTETOS (no caracteres): un acento son dos.
const plegar = (linea) => {
  const out = [];
  let actual = '';
  for (const ch of linea) {
    const limite = out.length ? 74 : 75; // las de continuación empiezan con un espacio
    if (Buffer.byteLength(actual + ch, 'utf8') > limite) { out.push(actual); actual = ch; }
    else actual += ch;
  }
  out.push(actual);
  return out.map((l, i) => (i ? ' ' + l : l)).join('\r\n');
};

const eventos = new Map();
for (const a of citas) {
  const rec = Array.isArray(a.recursos) ? a.recursos : [];
  // Solo las que ATIENDE: recurso `primary` cuyo empleado es este. Un participante
  // acompaña, no atiende; un recurso sin empleado (una sala, una clase) no es de nadie.
  // Sin `primary` no se adivina: la cita no va a ningún calendario.
  const prim = rec.find((x) => x.role === 'primary');
  const res = (prim && prim.resource_id) || {};
  const suyo = res.employee_id && (res.employee_id.id || res.employee_id) === emp.id;
  if (!suyo) continue;
  const grupo = Number(res.capacity) > 1;
  const servicio = (a.service_id && a.service_id.name) || a.title || 'Cita';
  const clave = grupo ? `grupo-${res.id}-${utc(a.start_at)}-${a.service_id && a.service_id.id}` : a.id;
  if (!eventos.has(clave)) eventos.set(clave, { a, servicio, grupo, citas: [] });
  eventos.get(clave).citas.push(a);
}

const ahora = utc(DateTime.now().toISO());
const lineas = [
  'BEGIN:VCALENDAR', 'VERSION:2.0', 'PRODID:-//Aegora//Calendario de citas//ES',
  'CALSCALE:GREGORIAN', 'METHOD:PUBLISH',
  `X-WR-CALNAME:${txt(`Citas de ${emp.first_name || 'mi agenda'} · ${negocio}`)}`,
  'X-WR-TIMEZONE:Europe/Madrid',
  // Cada cuánto PEDIMOS que se actualice. Outlook y Google lo ignoran y van a su ritmo
  // (horas); el calendario del iPhone y otros sí lo respetan.
  'REFRESH-INTERVAL;VALUE=DURATION:PT15M', 'X-PUBLISHED-TTL:PT15M',
];
for (const [clave, e] of eventos) {
  let resumen, descripcion;
  if (e.grupo) {
    const n = e.citas.length;
    resumen = `${e.servicio} · ${n} ${n === 1 ? 'apuntado' : 'apuntados'}`;
    descripcion = 'Apuntados:\n' + e.citas.map((c) => {
      const ct = c.contact_id || {};
      const extra = [ct.company, telefono(ct)].filter(Boolean).join(' · ');
      return '- ' + nombre(ct) + (extra ? ' — ' + extra : '');
    }).join('\n') + '\n\n' + PIE;
  } else {
    const ct = e.a.contact_id || {};
    resumen = `${e.servicio} · ${nombre(ct)}`;
    descripcion = [['Cliente', nombre(ct)], ['Empresa', ct.company], ['Teléfono', telefono(ct)]]
      .filter(([, v]) => v).map(([k, v]) => `${k}: ${v}`).join('\n')
      + (e.a.notes ? '\n\n' + e.a.notes : '') + '\n\n' + PIE;
  }
  const modificado = e.citas.map((c) => c.updated_at).filter(Boolean).sort().pop();
  lineas.push(
    'BEGIN:VEVENT',
    `UID:${clave}@aegora`,
    `DTSTAMP:${ahora}`,
    ...(modificado ? [`LAST-MODIFIED:${utc(modificado)}`] : []),
    `DTSTART:${utc(e.a.start_at)}`,
    `DTEND:${utc(e.a.end_at)}`,
    `SUMMARY:${txt(resumen)}`,
    `DESCRIPTION:${txt(descripcion)}`,
    'STATUS:CONFIRMED', 'TRANSP:OPAQUE', 'CATEGORIES:Aegora',
    'END:VEVENT',
  );
}
lineas.push('END:VCALENDAR');
return [{ json: { ics: lineas.map(plegar).join('\r\n') + '\r\n', eventos: eventos.size } }];

// El enlace depende de la dirección pública del tenant, que la base de datos no conoce:
// por eso lo escribe n8n y no el trigger que pone la clave. Solo se tocan los que
// cambian (empleado nuevo, o clave regenerada para invalidar el enlace anterior).
const cfg = $('Config (enlaces)').first().json;
const r = $json ?? {};
if (!(r.statusCode >= 200 && r.statusCode < 300)) {
  throw new Error('Directus devolvió ' + r.statusCode + ' al leer los empleados: ' + JSON.stringify(r.body).slice(0, 300));
}
const base = String(cfg.webhook_public_url).replace(/\/$/, '');
return ((r.body && r.body.data) || [])
  .filter((e) => e.calendario_token)
  .map((e) => ({ id: e.id, url: `${base}/webhook/calendario?k=${e.calendario_token}`, antes: e.calendario_url }))
  .filter((e) => e.url !== e.antes)
  .map((e) => ({ json: { id: e.id, calendario_url: e.url, directus_base_url: cfg.directus_base_url } }));
